public class DeliveryProbe {
 public static Integer seed=0;
 public static Integer flight=0;
 public static Integer hits=0;
 public static Integer count(String phase) {return [SELECT COUNT() FROM Account WHERE Name=:phase];}
 public static void save(String phase,Integer value) {insert new Account(Name=phase,NumberOfEmployees=value);}
 public static Integer value(String phase) {List<Account> rows=[SELECT NumberOfEmployees FROM Account WHERE Name=:phase];return rows.isEmpty()?-1:Integer.valueOf(rows[0].NumberOfEmployees);}
 public static void publishOne() {
  save('publisher seed',seed);
  flight=1;
  Database.SaveResult published=EventBus.publish(new DeliverySignal__e(Note__c='signal'));
  save('publish success',published.isSuccess()?1:0);
  save('publish errors',published.getErrors().size());
  save('publisher saw trigger',count('trigger'));
  flight=0;
  save('publisher after',1);
 }
 @future public static void publishFuture() {publishOne();}
 public static void receive() {
  save('trigger',1);
  save('trigger seed',seed);
  save('trigger flight',flight);
  save('trigger saw after',count('publisher after'));
  hits++;
 }
 public static Map<String,Integer> observe(String mode,String delivery) {
  seed=7;
  Map<String,Integer> result=new Map<String,Integer>();
  if(mode=='batch') insert new Account(Name='batch seed');
  Test.startTest();
  if(mode=='direct') publishOne();
  if(mode=='queue') System.enqueueJob(new DeliveryQueue());
  if(mode=='future') publishFuture();
  if(mode=='batch') Database.executeBatch(new DeliveryBatch(),1);
  result.put('beforeStop',count('trigger'));
  if(delivery=='before' || delivery=='both') Test.getEventBus().deliver();
  result.put('afterPreDeliver',count('trigger'));
  Test.stopTest();
  result.put('afterStop',count('trigger'));
  if(delivery=='after' || delivery=='both') Test.getEventBus().deliver();
  result.put('afterPostDeliver',count('trigger'));
  result.put('triggerSeed',value('trigger seed'));
  result.put('triggerFlight',value('trigger flight'));
  result.put('triggerSawAfter',value('trigger saw after'));
  result.put('publisherSawTrigger',value('publisher saw trigger'));
  result.put('publisherSeed',value('publisher seed'));
  result.put('publishSuccess',value('publish success'));
  result.put('publishErrors',value('publish errors'));
  result.put('testHits',hits);
  result.put('testSeed',seed);
  return result;
 }
}

